import Foundation

/// Whether the `git` / `jj` binaries on PATH are new enough for the VCS remote actions
/// (fetch/push/pull) to work at all.
///
/// **Why a declared floor rather than best-effort.** The remote commands fail *atomically* on an old
/// tool: `git for-each-ref --format='%(unknownatom)'` exits with `fatal: unknown field name` and
/// produces **no partial output**, and `jj bookmark` did not exist before ~0.18 (it was `jj branch`),
/// with the `tracking_*_count()` template functions newer still. The app bundles neither binary —
/// `ShellEnvironment.path()` takes whatever is on PATH — so without a floor a user on an old tool gets
/// raw stderr in place of every remote feature, with nothing telling them why.
///
/// **git is required; jj is optional.** No `git` is a broken install: the bundled Go CLI shells
/// `git worktree add` to create a workroom at all. No `jj` is the ordinary state for a git-only user
/// and must be completely silent — no warning, and not even a `jj --version` spawned.
///
/// **Scoping is per project VCS, not global.** An old `jj` must not disable a git project's toolbar.
/// An old `git` disables both, because a colocated jj repo drives git underneath (jj shells real `git`
/// for its network operations).
///
/// ```
///                    git ok        git belowFloor/absent
///   git project      enabled       disabled
///   jj  project      needs jj ok   disabled
/// ```
enum VCSToolVersions {
  /// The floors are anchored to something already true rather than picked.
  ///
  /// **git 2.41** is the minimum *jj itself* enforces for its git subprocess
  /// (`jj-lib`'s `MINIMUM_GIT_VERSION`), so it excludes nobody a jj user isn't already excluded by.
  /// Everything this app issues needs far less (`%(symref)` wants 2.8, `pull --autostash` wants 2.9),
  /// so the headroom is deliberate.
  static let gitFloor = SemanticVersion("2.41.0")!
  /// **jj 0.43** matches the `jj-lib` the Rust VCS core links. That matters beyond flags: an older CLI
  /// may not understand the repo format the linked library writes.
  static let jjFloor = SemanticVersion("0.43.0")!

  /// A tool's usability. `.unknown` is deliberately NOT a failure — see `isUsable`.
  enum Status: Equatable, Sendable {
    /// Found and at or above the floor. Carries the version string as printed, for copy.
    case ok(String)
    /// Found but too old. Carries the version string as printed.
    case belowFloor(String)
    /// Not on PATH (`/usr/bin/env` exits `CommandResult.commandNotFound`).
    case notInstalled
    /// The probe timed out, or its output didn't contain a parseable version.
    case unknown
  }

  /// A user-facing warning about one tool. Published to the notification list, not an alert — a too-old
  /// tool must never stop the app being useful for terminals and diffs, which issue none of these
  /// commands.
  struct ToolWarning: Equatable, Sendable, Identifiable {
    let tool: String
    let title: String
    let detail: String
    var id: String { tool }
  }

  struct Report: Equatable, Sendable {
    /// Required.
    let git: Status
    /// Optional — `.notInstalled` is not a problem on its own.
    let jj: Status

    /// Everything except `.belowFloor`/`.notInstalled` counts as usable.
    ///
    /// `.unknown` passes on purpose: a probe that timed out or printed something we couldn't parse is
    /// not evidence of an old tool, and disabling a working feature on a failed *guess* is worse than
    /// letting the command itself report a real error. Same never-cry-wolf rule
    /// `WorkroomStatusResolver.classifyGitHubCLI` follows for `gh`.
    static func isUsable(_ status: Status) -> Bool {
      switch status {
      case .ok, .unknown: return true
      case .belowFloor, .notInstalled: return false
      }
    }

    /// Whether remote actions are permitted for a project of this VCS (`"git"` / `"jj"`).
    func allowsRemoteActions(vcs: String) -> Bool {
      guard Self.isUsable(git) else { return false }
      return vcs == "jj" ? Self.isUsable(jj) : true
    }

    /// Warnings to publish. jj is only ever mentioned when a jj project is actually registered.
    func warnings(hasJJProject: Bool) -> [ToolWarning] {
      var out: [ToolWarning] = []
      switch git {
      case .notInstalled:
        out.append(
          ToolWarning(
            tool: "git", title: "Git isn’t installed",
            detail:
              "Workroom needs Git to manage workrooms. Install it with `xcode-select --install`, "
              + "or from Homebrew, then restart Workroom."))
      case .belowFloor(let found):
        out.append(
          ToolWarning(
            tool: "git", title: "Git \(gitFloor.shortDescription) or newer is required",
            detail:
              "Found Git \(found). Fetch, push and pull are disabled until you upgrade — the commands "
              + "they use don’t exist in this version."))
      case .ok, .unknown:
        break
      }
      guard hasJJProject else { return out }
      switch jj {
      case .notInstalled:
        out.append(
          ToolWarning(
            tool: "jj", title: "Jujutsu isn’t installed",
            detail:
              "One or more of your projects uses Jujutsu. Fetch, push and pull are disabled for them "
              + "until `jj` is on your PATH."))
      case .belowFloor(let found):
        out.append(
          ToolWarning(
            tool: "jj", title: "Jujutsu \(jjFloor.shortDescription) or newer is required",
            detail:
              "Found jj \(found). Fetch, push and pull are disabled for your Jujutsu projects until "
              + "you upgrade."))
      case .ok, .unknown:
        break
      }
      return out
    }
  }

  /// The first whitespace-separated token that parses as a version.
  ///
  /// Handles every form these tools print: `git version 2.55.0`, Apple's
  /// `git version 2.39.5 (Apple Git-154)`, and `jj 0.43.0`. Non-numeric tokens (`git`, `version`,
  /// `(Apple`, `Git-154)`) can't parse — `SemanticVersion` requires a numeric core — so no allowlist
  /// of leading words is needed, and a future rewording of the prefix won't break this.
  static func firstVersion(in output: String) -> (raw: String, parsed: SemanticVersion)? {
    for token in output.split(whereSeparator: { $0.isWhitespace }) {
      let raw = String(token)
      if let parsed = SemanticVersion(raw) { return (raw, parsed) }
    }
    return nil
  }

  /// Classify one `--version` result against a floor.
  static func status(_ result: CommandResult, floor: SemanticVersion) -> Status {
    if result.exitCode == CommandResult.commandNotFound { return .notInstalled }
    if result.timedOut { return .unknown }
    // Some tools print `--version` to stderr; check both rather than assuming.
    guard let found = firstVersion(in: result.stdout + " " + result.stderr) else { return .unknown }
    return found.parsed < floor ? .belowFloor(found.raw) : .ok(found.raw)
  }

  /// Probe both tools. `probeJJ` false ⇒ `jj` is not run at all and reports `.notInstalled`, which
  /// `warnings(hasJJProject:)` then ignores.
  ///
  /// Local reads, so `run` not `runNetwork`. Called in the background at app start, never blocking
  /// launch — and only *after* `ShellEnvironment` has set the PATH floor, since the probe needs PATH
  /// to find the binaries in the first place.
  static func probe(
    runner: StatusCommandRunning = StatusCommandRunner(), probeJJ: Bool,
    timeout: TimeInterval = 5, directory: String = NSTemporaryDirectory()
  ) async -> Report {
    let gitResult = await runner.run("git", ["--version"], in: directory, timeout: timeout)
    let gitStatus = status(gitResult, floor: gitFloor)
    guard probeJJ else { return Report(git: gitStatus, jj: .notInstalled) }
    let jjResult = await runner.run("jj", ["--version"], in: directory, timeout: timeout)
    return Report(git: gitStatus, jj: status(jjResult, floor: jjFloor))
  }
}

extension SemanticVersion {
  /// `"2.41"` for a zero patch, else `"2.41.1"` — how a required version reads in prose.
  var shortDescription: String {
    let padded = core + Array(repeating: 0, count: max(0, 3 - core.count))
    let base = padded[2] == 0 ? "\(padded[0]).\(padded[1])" : "\(padded[0]).\(padded[1]).\(padded[2])"
    return prerelease.isEmpty ? base : base + "-" + prerelease.joined(separator: ".")
  }
}

import XCTest

@testable import Workroom

/// `VCSToolVersions` — the declared tool floors (git 2.41 required, jj 0.43 optional) and the
/// per-project-VCS scoping of what a below-floor tool disables.
///
/// The parsing tests exist because the remote commands fail *atomically* on an old tool, so a
/// mis-parsed version silently either blocks a working install or admits a broken one. The scoping
/// tests are the ones most likely to catch a regression: it is easy to write a global "tools ok?"
/// boolean that wrongly lets an old `jj` disable a git project's toolbar.
final class VCSToolVersionsTests: XCTestCase {

  private func result(_ stdout: String, exit: Int32 = 0, timedOut: Bool = false) -> CommandResult {
    CommandResult(stdout: stdout, stderr: "", exitCode: exit, timedOut: timedOut)
  }

  // MARK: Parsing

  func testParsesGitVersion() {
    XCTAssertEqual(VCSToolVersions.firstVersion(in: "git version 2.55.0")?.raw, "2.55.0")
  }

  /// Apple's git appends a build suffix in parentheses. `(Apple` and `Git-154)` must not be mistaken
  /// for the version.
  func testParsesAppleGitVersion() {
    let found = VCSToolVersions.firstVersion(in: "git version 2.39.5 (Apple Git-154)")
    XCTAssertEqual(found?.raw, "2.39.5")
  }

  func testParsesJJVersion() {
    XCTAssertEqual(VCSToolVersions.firstVersion(in: "jj 0.43.0")?.raw, "0.43.0")
  }

  func testParsesTwoComponentVersion() {
    XCTAssertEqual(VCSToolVersions.firstVersion(in: "git version 2.41")?.parsed.core, [2, 41, 0])
  }

  func testRejectsOutputWithNoVersion() {
    XCTAssertNil(VCSToolVersions.firstVersion(in: "command not found"))
    XCTAssertNil(VCSToolVersions.firstVersion(in: ""))
    XCTAssertNil(VCSToolVersions.firstVersion(in: "   \n  "))
  }

  // MARK: Floors

  /// Exactly at the floor must PASS. An off-by-one here locks out the version we chose to support.
  func testExactlyAtTheGitFloorIsOk() {
    XCTAssertEqual(
      VCSToolVersions.status(result("git version 2.41.0"), floor: VCSToolVersions.gitFloor),
      .ok("2.41.0"))
  }

  func testJustBelowTheGitFloorIsBelowFloor() {
    XCTAssertEqual(
      VCSToolVersions.status(result("git version 2.40.9"), floor: VCSToolVersions.gitFloor),
      .belowFloor("2.40.9"))
    XCTAssertEqual(
      VCSToolVersions.status(result("git version 2.39.5 (Apple Git-154)"),
                             floor: VCSToolVersions.gitFloor),
      .belowFloor("2.39.5"))
  }

  func testAboveTheFloorIsOk() {
    XCTAssertEqual(
      VCSToolVersions.status(result("git version 2.55.0"), floor: VCSToolVersions.gitFloor),
      .ok("2.55.0"))
    XCTAssertEqual(
      VCSToolVersions.status(result("jj 0.43.0"), floor: VCSToolVersions.jjFloor), .ok("0.43.0"))
  }

  func testBelowTheJJFloor() {
    XCTAssertEqual(
      VCSToolVersions.status(result("jj 0.17.0"), floor: VCSToolVersions.jjFloor),
      .belowFloor("0.17.0"))
  }

  // MARK: Statuses

  func testExit127IsNotInstalledNotBelowFloor() {
    XCTAssertEqual(
      VCSToolVersions.status(result("", exit: CommandResult.commandNotFound),
                             floor: VCSToolVersions.gitFloor),
      .notInstalled)
  }

  func testTimeoutIsUnknown() {
    XCTAssertEqual(
      VCSToolVersions.status(result("", timedOut: true), floor: VCSToolVersions.gitFloor), .unknown)
  }

  func testUnparseableOutputIsUnknown() {
    XCTAssertEqual(
      VCSToolVersions.status(result("wat"), floor: VCSToolVersions.gitFloor), .unknown)
  }

  func testVersionOnStderrIsStillRead() {
    let r = CommandResult(stdout: "", stderr: "jj 0.43.0", exitCode: 0, timedOut: false)
    XCTAssertEqual(VCSToolVersions.status(r, floor: VCSToolVersions.jjFloor), .ok("0.43.0"))
  }

  /// Never cry wolf: an unreadable probe must not disable a feature that may well work.
  func testUnknownIsTreatedAsUsable() {
    let report = VCSToolVersions.Report(git: .unknown, jj: .unknown)
    XCTAssertTrue(report.allowsRemoteActions(vcs: "git"))
    XCTAssertTrue(report.allowsRemoteActions(vcs: "jj"))
    XCTAssertTrue(report.warnings(hasJJProject: true).isEmpty)
  }

  // MARK: Required vs optional, and per-VCS scoping

  func testEverythingOkAllowsBoth() {
    let report = VCSToolVersions.Report(git: .ok("2.55.0"), jj: .ok("0.43.0"))
    XCTAssertTrue(report.allowsRemoteActions(vcs: "git"))
    XCTAssertTrue(report.allowsRemoteActions(vcs: "jj"))
    XCTAssertTrue(report.warnings(hasJJProject: true).isEmpty)
  }

  /// jj is OPTIONAL: a git-only user must never be warned about a tool they don't use.
  func testMissingJJIsSilentWithoutAJJProject() {
    let report = VCSToolVersions.Report(git: .ok("2.55.0"), jj: .notInstalled)
    XCTAssertTrue(report.warnings(hasJJProject: false).isEmpty)
    XCTAssertTrue(report.allowsRemoteActions(vcs: "git"))
  }

  /// …but with a jj project registered it is worth saying, and it disables jj projects ONLY.
  func testMissingJJWarnsAndDisablesOnlyJJProjects() {
    let report = VCSToolVersions.Report(git: .ok("2.55.0"), jj: .notInstalled)
    let warnings = report.warnings(hasJJProject: true)
    XCTAssertEqual(warnings.count, 1)
    XCTAssertEqual(warnings.first?.tool, "jj")
    XCTAssertTrue(
      report.allowsRemoteActions(vcs: "git"), "an absent jj must NOT disable a git project")
    XCTAssertFalse(report.allowsRemoteActions(vcs: "jj"))
  }

  func testOldJJDisablesOnlyJJProjects() {
    let report = VCSToolVersions.Report(git: .ok("2.55.0"), jj: .belowFloor("0.17.0"))
    XCTAssertTrue(
      report.allowsRemoteActions(vcs: "git"), "an old jj must NOT disable a git project")
    XCTAssertFalse(report.allowsRemoteActions(vcs: "jj"))
    XCTAssertEqual(report.warnings(hasJJProject: true).map(\.tool), ["jj"])
  }

  /// git is REQUIRED, and a colocated jj repo drives git underneath — so an old git disables both.
  func testOldGitDisablesBothVCSKinds() {
    let report = VCSToolVersions.Report(git: .belowFloor("2.30.0"), jj: .ok("0.43.0"))
    XCTAssertFalse(report.allowsRemoteActions(vcs: "git"))
    XCTAssertFalse(report.allowsRemoteActions(vcs: "jj"), "jj drives git for its network ops")
    XCTAssertEqual(report.warnings(hasJJProject: false).map(\.tool), ["git"])
  }

  func testAbsentGitDisablesBothAndUsesBrokenInstallCopy() {
    let report = VCSToolVersions.Report(git: .notInstalled, jj: .ok("0.43.0"))
    XCTAssertFalse(report.allowsRemoteActions(vcs: "git"))
    XCTAssertFalse(report.allowsRemoteActions(vcs: "jj"))
    let warning = report.warnings(hasJJProject: false).first
    XCTAssertEqual(warning?.tool, "git")
    XCTAssertTrue(
      warning?.title.contains("isn’t installed") == true,
      "absent git needs broken-install copy, not too-old copy: \(warning?.title ?? "nil")")
  }

  func testBothBrokenWarnsAboutBoth() {
    let report = VCSToolVersions.Report(git: .belowFloor("2.30.0"), jj: .belowFloor("0.17.0"))
    XCTAssertEqual(report.warnings(hasJJProject: true).map(\.tool), ["git", "jj"])
  }

  // MARK: Probe

  /// `probeJJ: false` must not spawn `jj --version` at all — a git-only user shouldn't pay for a
  /// process, and `env` would report 127 for a tool they legitimately don't have.
  func testProbeSkipsJJEntirelyWhenNotNeeded() async {
    let runner = RecordingVersionRunner(
      responses: ["git": CommandResult(stdout: "git version 2.55.0", stderr: "", exitCode: 0,
                                       timedOut: false)])
    let report = await VCSToolVersions.probe(runner: runner, probeJJ: false)
    XCTAssertEqual(report.git, .ok("2.55.0"))
    XCTAssertEqual(await runner.executables(), ["git"], "jj must not be spawned")
    XCTAssertTrue(report.warnings(hasJJProject: false).isEmpty)
  }

  func testProbeReadsBothWhenJJIsNeeded() async {
    let runner = RecordingVersionRunner(
      responses: [
        "git": CommandResult(stdout: "git version 2.55.0", stderr: "", exitCode: 0, timedOut: false),
        "jj": CommandResult(stdout: "jj 0.43.0", stderr: "", exitCode: 0, timedOut: false),
      ])
    let report = await VCSToolVersions.probe(runner: runner, probeJJ: true)
    XCTAssertEqual(report.git, .ok("2.55.0"))
    XCTAssertEqual(report.jj, .ok("0.43.0"))
    XCTAssertEqual(await runner.executables(), ["git", "jj"])
  }

  func testProbeAsksForVersionFlag() async {
    let runner = RecordingVersionRunner(
      responses: ["git": CommandResult(stdout: "git version 2.55.0", stderr: "", exitCode: 0,
                                       timedOut: false)])
    _ = await VCSToolVersions.probe(runner: runner, probeJJ: false)
    XCTAssertEqual(await runner.calls().first?.args, ["--version"])
  }

  // MARK: Copy

  func testRequiredVersionReadsAsTwoComponentsWhenPatchIsZero() {
    XCTAssertEqual(VCSToolVersions.gitFloor.shortDescription, "2.41")
    XCTAssertEqual(VCSToolVersions.jjFloor.shortDescription, "0.43")
    XCTAssertEqual(SemanticVersion("1.2.3")!.shortDescription, "1.2.3")
  }

  func testBelowFloorCopyNamesBothFoundAndRequired() {
    let report = VCSToolVersions.Report(git: .belowFloor("2.30.0"), jj: .ok("0.43.0"))
    let warning = report.warnings(hasJJProject: false).first
    XCTAssertTrue(warning?.title.contains("2.41") == true, "must name the requirement")
    XCTAssertTrue(warning?.detail.contains("2.30.0") == true, "must name what was found")
  }
}

/// Records which executables were asked for, so a test can assert `jj` was never spawned.
private actor RecordingVersionRunner: StatusCommandRunning {
  struct Call: Sendable {
    let executable: String
    let args: [String]
  }

  private var recorded: [Call] = []
  private let responses: [String: CommandResult]

  init(responses: [String: CommandResult]) { self.responses = responses }

  func executables() -> [String] { recorded.map(\.executable) }
  func calls() -> [Call] { recorded }

  nonisolated func run(
    _ executable: String, _ args: [String], in directory: String, timeout: TimeInterval
  ) async -> CommandResult {
    await record(executable, args)
    return responses[executable]
      ?? CommandResult(stdout: "", stderr: "", exitCode: CommandResult.commandNotFound,
                       timedOut: false)
  }

  private func record(_ executable: String, _ args: [String]) {
    recorded.append(Call(executable: executable, args: args))
  }
}

