import Foundation

/// What the VCS toolbar's middle segment is currently doing.
enum VCSSyncActivity: Equatable, Sendable {
  case idle
  case running(VCSRemoteAction)
}

/// Everything the toolbar's sync segment renders, resolved from one state snapshot.
///
/// A pure mapping, kept out of the view for the same reason as `ChangeBadge`: it's a many-case
/// decision that silently drifts. `now` is a parameter rather than a `Date()` read so the whole thing
/// is testable at fixed instants.
struct VCSSyncPresentation: Equatable, Sendable {
  /// Title variants, LONGEST FIRST, for a `ViewThatFits` ladder. Empty ⇒ single-line mode: the segment
  /// renders only `subtitle`, vertically centred, at a larger weight.
  var titleVariants: [String] = []
  var subtitle: String
  /// A shorter subtitle for narrow widths. The staleness caveat abbreviates but must never be the
  /// first thing dropped — the unverified count it qualifies is the thing that should yield.
  var subtitleShort: String
  var symbol: String?
  var badge: Badge?
  var secondaryBadge: Badge?
  var action: VCSRemoteAction?
  var isEnabled: Bool
  var tone: Tone = .normal
  var help: String
  /// Spoken label. The count pills are `accessibilityHidden`, so their information has to arrive here.
  var accessibility: String
  var accessibilityValue: String = ""

  struct Badge: Equatable, Sendable {
    enum Direction: Equatable, Sendable { case ahead, behind }
    let count: Int
    let direction: Direction
  }

  enum Tone: Equatable, Sendable { case normal, warning, failure }

  var title: String? { titleVariants.first }
  var isSingleLine: Bool { titleVariants.isEmpty }
}

/// Maps a `VCSRemoteState` to what the sync segment shows.
///
/// ```
///   failure?  ──yes──►  [13] retry the previous action          tone: failure
///      │no
///   in flight? ──yes──►  [10/11/12] Fetching…/Pushing…/Pulling…      disabled
///      │no
///   target valid? ──no──►  [1] no workroom  ·  [2] no repository     disabled
///      │yes
///   tools ok? ──no──►  [0] "<tool> is too old"                       disabled
///      │yes
///   has remote? ──no───►  [3] "No remote configured"                 disabled
///      │yes
///   counterpart gone? ──yes──►  [4] "Publish branch"      → push --set-upstream
///      │no
///   ahead>0 && behind>0 ──yes──►  [9] "Pull <remote> with rebase"   badge: M↓ then N↑
///      │no                             (pull, NOT push — git refuses non-ff)
///   behind>0 ──yes──►  [8] "Pull <remote> with rebase"              badge: M↓
///      │no
///   ahead>0  ──yes──►  [7] "Push <remote>"                          badge: N↑
///      │no
///   never fetched ──yes──►  [5] "Never fetched"          → fetch
///      │no
///                        [6] "Last fetched <rel>"        → fetch
/// ```
///
/// `<remote>` is always interpolated from `primaryRemote`, never the literal "origin" —
/// `remote.pushDefault` can legitimately make that the wrong name.
enum VCSSyncPresenter {

  /// Build the presentation.
  ///
  /// - Parameters:
  ///   - state: `nil` ⇒ no readable repo for the current target.
  ///   - hasTarget: whether a workroom is selected at all (distinguishes "nothing selected" from
  ///     "selected, but not a repo" — different copy, both disabled).
  ///   - toolsUsable: `false` ⇒ the `git`/`jj` on PATH can't run these commands
  ///     (`VCSToolVersions`). Outranks everything except an in-flight action and a failure, because no
  ///     action can succeed.
  ///   - pullRebase: whether the repo pulls with rebase — wording only.
  static func make(
    state: VCSRemoteState?, hasTarget: Bool, toolsUsable: Bool = true,
    activity: VCSSyncActivity = .idle, failure: VCSRemoteFailure? = nil,
    lastAction: VCSRemoteAction? = nil, pullRebase: Bool = true, now: Date
  ) -> VCSSyncPresentation {
    // [13] A failure outranks everything: it's the only state with something to recover from, and
    // burying it under a count would leave the user with no idea the action didn't happen.
    if let failure, case .idle = activity {
      let message = describe(failure)
      return VCSSyncPresentation(
        titleVariants: (lastAction?.label).map { [$0] } ?? ["Retry"],
        subtitle: message, subtitleShort: message,
        symbol: "exclamationmark.triangle.fill",
        action: retryAction(for: failure, lastAction: lastAction),
        isEnabled: retryAction(for: failure, lastAction: lastAction) != nil,
        tone: .failure, help: message, accessibility: "\(lastAction?.label ?? "Action") failed. \(message)")
    }

    // [10/11/12] In flight — one action at a time, so this can't collide with a second.
    if case .running(let action) = activity {
      let title: String
      let subtitle: String
      switch action {
      case .fetch: (title, subtitle) = ("Fetching…", "from \(state?.primaryRemote ?? "remote")")
      case .push: (title, subtitle) = ("Pushing…", "to \(state?.primaryRemote ?? "remote")")
      case .pull: (title, subtitle) = ("Pulling…", "from \(state?.primaryRemote ?? "remote")")
      case .abortRebase: (title, subtitle) = ("Aborting…", "rebase")
      }
      return VCSSyncPresentation(
        titleVariants: [title], subtitle: subtitle, subtitleShort: subtitle,
        symbol: nil, badge: badge(ahead: state?.tracking?.ahead),
        action: nil, isEnabled: false, help: "\(title) \(subtitle)",
        accessibility: "\(title) \(subtitle)")
    }

    // [1] Nothing selected.
    guard hasTarget else {
      return disabled("No workroom selected", symbol: nil)
    }
    // [2] Selected, but not a readable repo.
    guard let state else {
      return disabled("No repository", symbol: "exclamationmark.triangle", tone: .warning)
    }
    // [0] The tools can't run these commands. Nothing below this line could succeed.
    guard toolsUsable else {
      return disabled(
        "Update git to use this", symbol: "exclamationmark.triangle", tone: .warning,
        help: "Fetch, push and pull need a newer git or jj. See the warning for the required version.")
    }
    // [3] No remote at all.
    guard let remote = state.primaryRemote else {
      return disabled("No remote configured", symbol: nil)
    }

    let fetched = fetchedAgo(state.lastFetch, now: now)
    let fetchedShort = fetchedAgo(state.lastFetch, now: now, short: true)
    let tracking = state.tracking

    // [4] No counterpart on the remote yet. This is the DEFAULT state of a fresh workroom —
    // `git worktree add -b` sets no upstream — so it must not read as "Push origin" against something
    // that doesn't exist.
    if let tracking, tracking.gone {
      let branch = state.current.name ?? "this branch"
      let detail = "\(branch) isn’t on \(remote) yet"
      return VCSSyncPresentation(
        titleVariants: ["Publish branch", "Publish"],
        subtitle: detail, subtitleShort: detail, symbol: "arrow.up.circle",
        badge: badge(ahead: tracking.ahead), action: .push, isEnabled: true,
        help: "Push \(branch) to \(remote) and start tracking it.",
        accessibility: "Publish branch. \(detail)")
    }

    let ahead = tracking?.ahead ?? 0
    let behind = tracking?.behind ?? 0
    let pullTitles =
      pullRebase
      ? ["Pull \(remote) with rebase", "Pull with rebase", "Pull"]
      : ["Pull \(remote)", "Pull"]

    // [9] Diverged ⇒ Pull, not Push: git refuses a non-fast-forward push, so offering Push here would
    // send the user straight into a rejection. Badges show both, ↓ first — the one the action addresses.
    if ahead > 0, behind > 0 {
      return VCSSyncPresentation(
        titleVariants: pullTitles, subtitle: fetched, subtitleShort: fetchedShort,
        symbol: "arrow.up.arrow.down",
        badge: Badge(count: behind, direction: .behind),
        secondaryBadge: Badge(count: ahead, direction: .ahead),
        action: .pull, isEnabled: true,
        help:
          "\(ahead) to push, \(behind) to pull. Pull first — \(remote) will reject a non-fast-forward push.",
        accessibility: "Pull \(remote) with rebase",
        accessibilityValue: "\(behind) behind, \(ahead) ahead")
    }
    // [8] Behind only.
    if behind > 0 {
      return VCSSyncPresentation(
        titleVariants: pullTitles, subtitle: fetched, subtitleShort: fetchedShort,
        symbol: "arrow.down", badge: Badge(count: behind, direction: .behind),
        action: .pull, isEnabled: true,
        help: "\(behind) commit\(behind == 1 ? "" : "s") to pull from \(remote). \(fetched).",
        accessibility: "Pull \(remote) with rebase", accessibilityValue: "\(behind) behind")
    }
    // [7] Ahead only.
    if ahead > 0 {
      return VCSSyncPresentation(
        titleVariants: ["Push \(remote)", "Push"], subtitle: fetched, subtitleShort: fetchedShort,
        symbol: "arrow.up", badge: Badge(count: ahead, direction: .ahead),
        action: .push, isEnabled: true,
        help: "\(ahead) commit\(ahead == 1 ? "" : "s") to push to \(remote). \(fetched).",
        accessibility: "Push \(remote)", accessibilityValue: "\(ahead) ahead")
    }
    // [5]/[6] In sync — the segment becomes a Fetch button.
    return VCSSyncPresentation(
      subtitle: fetched, subtitleShort: fetchedShort, symbol: nil,
      action: .fetch, isEnabled: true,
      help: "Up to date with \(remote). \(fetched). Click to fetch again.",
      accessibility: "Fetch \(remote). \(fetched)")
  }

  private static func disabled(
    _ subtitle: String, symbol: String?, tone: VCSSyncPresentation.Tone = .normal,
    help: String? = nil
  ) -> VCSSyncPresentation {
    VCSSyncPresentation(
      subtitle: subtitle, subtitleShort: subtitle, symbol: symbol, action: nil, isEnabled: false,
      tone: tone, help: help ?? subtitle, accessibility: subtitle)
  }

  private static func badge(ahead: Int?) -> VCSSyncPresentation.Badge? {
    guard let ahead, ahead > 0 else { return nil }
    return VCSSyncPresentation.Badge(count: ahead, direction: .ahead)
  }

  /// Which action a failure offers. `.rebaseInProgress` deliberately offers **Abort**, never a retry —
  /// a retry fails identically until the rebase is cleared. `.toolMissing` offers nothing, because no
  /// click can fix a missing binary.
  static func retryAction(for failure: VCSRemoteFailure, lastAction: VCSRemoteAction?)
    -> VCSRemoteAction?
  {
    switch failure {
    case .rebaseInProgress: return .abortRebase
    case .rejected: return .pull  // the fix for a rejection is to pull, never to force
    case .toolMissing, .noRemote: return nil
    default: return lastAction
    }
  }

  /// One-line, actionable copy per failure. The raw stderr is legible for some cases and baffling for
  /// others, so the baffling ones get written copy.
  static func describe(_ failure: VCSRemoteFailure) -> String {
    switch failure {
    case .toolMissing(let tool):
      return "\(tool) isn’t on Workroom’s PATH."
    case .timedOut(let action):
      return "\(action.label) timed out."
    case .authRequired:
      // The #1 expected failure. The runner sets GIT_TERMINAL_PROMPT=0 and ssh BatchMode, so this
      // fails instantly rather than hanging — but the raw stderr is baffling, hence bespoke copy.
      return "Couldn’t authenticate. Load your key into ssh-agent, or set a credential helper."
    case .hostKeyUnverified:
      return "The host’s key isn’t known. Connect once from a terminal to accept it."
    case .noRemote:
      return "No remote configured."
    case .rejected:
      return "Rejected — \(String("the remote has commits you don’t. Pull first."))"
    case .dirtyWorkingTree:
      return "Uncommitted changes are in the way. Commit or stash them first."
    case .rebaseInProgress:
      return "A rebase is in progress. Abort it to continue."
    case .locked:
      return "The repository was busy. Try again."
    case .other(let message):
      return message.split(whereSeparator: \.isNewline).first.map(String.init) ?? "Failed."
    }
  }

  // MARK: Relative time

  private static let fullFormatter: RelativeDateTimeFormatter = {
    let f = RelativeDateTimeFormatter()
    f.unitsStyle = .full
    return f
  }()

  private static let shortFormatter: RelativeDateTimeFormatter = {
    let f = RelativeDateTimeFormatter()
    f.unitsStyle = .abbreviated
    return f
  }()

  /// "Last fetched 9 minutes ago" / "Fetched 9 min. ago" / "Never fetched" / "".
  ///
  /// Under a minute reads "just now" rather than "in 0 seconds", which is what
  /// `RelativeDateTimeFormatter` produces for a sub-second delta.
  ///
  /// `.unknown` renders NOTHING — never the word "never". They are different facts: `.never` means we
  /// looked and there was no fetch; `.unknown` means we couldn't tell.
  static func fetchedAgo(_ lastFetch: VCSLastFetch, now: Date, short: Bool = false) -> String {
    switch lastFetch {
    case .never: return "Never fetched"
    case .unknown: return ""
    case .at(let date):
      let prefix = short ? "Fetched" : "Last fetched"
      if now.timeIntervalSince(date) < 60 { return "\(prefix) just now" }
      let formatter = short ? shortFormatter : fullFormatter
      return "\(prefix) \(formatter.localizedString(for: date, relativeTo: now))"
    }
  }
}

import XCTest

@testable import Workroom

/// `VCSSyncPresenter` — the toolbar's middle-segment state machine.
///
/// A pure mapping with a hand-ordered precedence, which is exactly the shape that drifts silently
/// (`ChangeBadge`'s doc records how its own switch drifted once already). Every state and every
/// precedence edge is pinned here, before any view exists.
///
/// The single most important test in this file is `testNoCounterpartOffersPublishNotPush`: a fresh
/// workroom is `git worktree add -b` with no upstream, so "no counterpart" is the DEFAULT state, and
/// getting it wrong makes every new workroom read "Push origin" against a ref that doesn't exist.
final class VCSSyncPresentationTests: XCTestCase {

  private let now = Date(timeIntervalSince1970: 1_700_000_000)

  private func state(
    branch: String? = "main", kind: VCSRefKind = .branch, ahead: Int? = 0, behind: Int? = 0,
    gone: Bool = false, hasTracking: Bool = true, remotes: [String] = ["origin"],
    lastFetch: VCSLastFetch = .at(Date(timeIntervalSince1970: 1_699_999_460))  // 9 minutes before
  ) -> VCSRemoteState {
    VCSRemoteState(
      current: VCSRef(name: branch, kind: kind),
      tracking: hasTracking
        ? VCSTracking(comparedTo: "origin/\(branch ?? "?")", ahead: ahead, behind: behind, gone: gone)
        : nil,
      remotes: remotes, primaryRemote: CLIVCSWriter.primaryRemote(remotes),
      lastFetch: lastFetch, resolvedAt: now)
  }

  // MARK: States

  func testNoTargetIsDisabled() {
    let p = VCSSyncPresenter.make(state: nil, hasTarget: false, now: now)
    XCTAssertEqual(p.subtitle, "No workroom selected")
    XCTAssertFalse(p.isEnabled)
    XCTAssertNil(p.action)
    XCTAssertTrue(p.isSingleLine)
  }

  func testTargetWithNoRepoIsDisabled() {
    let p = VCSSyncPresenter.make(state: nil, hasTarget: true, now: now)
    XCTAssertEqual(p.subtitle, "No repository")
    XCTAssertFalse(p.isEnabled)
    XCTAssertEqual(p.tone, .warning)
  }

  func testNoRemoteIsDisabled() {
    let p = VCSSyncPresenter.make(state: state(remotes: []), hasTarget: true, now: now)
    XCTAssertEqual(p.subtitle, "No remote configured")
    XCTAssertFalse(p.isEnabled)
    XCTAssertNil(p.action)
  }

  /// THE workroom default. `git worktree add -b` sets no upstream, so the counterpart is absent for
  /// every freshly created workroom — this must offer Publish, never Push against a missing ref.
  func testNoCounterpartOffersPublishNotPush() {
    let p = VCSSyncPresenter.make(
      state: state(branch: "workroom/coral-bone", ahead: nil, behind: nil, gone: true),
      hasTarget: true, now: now)
    XCTAssertEqual(p.title, "Publish branch")
    XCTAssertEqual(p.action, .push)
    XCTAssertTrue(p.isEnabled)
    XCTAssertTrue(p.subtitle.contains("workroom/coral-bone"))
    XCTAssertTrue(p.subtitle.contains("isn’t on origin yet"))
  }

  func testAheadOffersPush() {
    let p = VCSSyncPresenter.make(state: state(ahead: 5, behind: 0), hasTarget: true, now: now)
    XCTAssertEqual(p.title, "Push origin")
    XCTAssertEqual(p.action, .push)
    XCTAssertEqual(p.badge, .init(count: 5, direction: .ahead))
    XCTAssertNil(p.secondaryBadge)
    XCTAssertEqual(p.subtitle, "Last fetched 9 minutes ago")
    XCTAssertEqual(p.accessibilityValue, "5 ahead")
  }

  func testBehindOffersPullWithRebase() {
    let p = VCSSyncPresenter.make(state: state(ahead: 0, behind: 3), hasTarget: true, now: now)
    XCTAssertEqual(p.title, "Pull origin with rebase")
    XCTAssertEqual(p.action, .pull)
    XCTAssertEqual(p.badge, .init(count: 3, direction: .behind))
    XCTAssertEqual(p.accessibilityValue, "3 behind")
  }

  func testPullWordingDropsRebaseWhenTheRepoDoesNotRebase() {
    let p = VCSSyncPresenter.make(
      state: state(ahead: 0, behind: 3), hasTarget: true, pullRebase: false, now: now)
    XCTAssertEqual(p.title, "Pull origin")
  }

  /// Diverged offers PULL, not push: git refuses a non-fast-forward push, so Push here would send the
  /// user straight into a rejection. Badges show behind FIRST — the one the action addresses.
  func testDivergedOffersPullAndShowsBehindFirst() {
    let p = VCSSyncPresenter.make(state: state(ahead: 2, behind: 4), hasTarget: true, now: now)
    XCTAssertEqual(p.action, .pull, "git refuses a non-fast-forward push")
    XCTAssertEqual(p.badge?.direction, .behind, "the badge the action addresses comes first")
    XCTAssertEqual(p.badge?.count, 4)
    XCTAssertEqual(p.secondaryBadge, .init(count: 2, direction: .ahead))
    XCTAssertEqual(p.accessibilityValue, "4 behind, 2 ahead")
  }

  func testInSyncBecomesAFetchButton() {
    let p = VCSSyncPresenter.make(state: state(ahead: 0, behind: 0), hasTarget: true, now: now)
    XCTAssertEqual(p.action, .fetch)
    XCTAssertTrue(p.isEnabled)
    XCTAssertTrue(p.isSingleLine, "nothing to say beyond the timestamp")
    XCTAssertEqual(p.subtitle, "Last fetched 9 minutes ago")
    XCTAssertNil(p.badge)
  }

  func testNeverFetchedStillOffersFetch() {
    let p = VCSSyncPresenter.make(state: state(lastFetch: .never), hasTarget: true, now: now)
    XCTAssertEqual(p.subtitle, "Never fetched")
    XCTAssertEqual(p.action, .fetch)
    XCTAssertTrue(p.isEnabled)
  }

  /// A detached HEAD (or a jj `@` with nothing to compare) has no tracking at all — that's in-sync-ish,
  /// not an error, and Fetch is still meaningful.
  func testNoTrackingFallsThroughToFetch() {
    let p = VCSSyncPresenter.make(
      state: state(kind: .detached, hasTracking: false), hasTarget: true, now: now)
    XCTAssertEqual(p.action, .fetch)
    XCTAssertNil(p.badge)
  }

  // MARK: Tool floor

  /// A below-floor tool outranks every count: no action below it could succeed, so offering one would
  /// be a lie. The warning toast carries the version detail; this segment just has to stop inviting.
  func testUnusableToolsDisableTheSegment() {
    let p = VCSSyncPresenter.make(
      state: state(ahead: 5), hasTarget: true, toolsUsable: false, now: now)
    XCTAssertFalse(p.isEnabled)
    XCTAssertNil(p.action)
    XCTAssertEqual(p.tone, .warning)
  }

  // MARK: In flight

  func testInFlightShowsProgressAndDisables() {
    for action in [VCSRemoteAction.fetch, .push, .pull] {
      let p = VCSSyncPresenter.make(
        state: state(ahead: 5), hasTarget: true, activity: .running(action), now: now)
      XCTAssertFalse(p.isEnabled, "\(action) in flight must disable")
      XCTAssertNil(p.action, "no second click while one is running")
      XCTAssertTrue(p.title?.hasSuffix("…") == true, "got \(p.title ?? "nil")")
    }
  }

  func testInFlightKeepsTheCountVisible() {
    let p = VCSSyncPresenter.make(
      state: state(ahead: 5), hasTarget: true, activity: .running(.push), now: now)
    XCTAssertEqual(p.badge, .init(count: 5, direction: .ahead))
  }

  // MARK: Failures

  func testFailureOutranksAnAvailableCount() {
    let p = VCSSyncPresenter.make(
      state: state(ahead: 5), hasTarget: true, failure: .authRequired("boom"), lastAction: .push,
      now: now)
    XCTAssertEqual(p.tone, .failure)
    XCTAssertEqual(p.symbol, "exclamationmark.triangle.fill")
    XCTAssertTrue(p.subtitle.contains("authenticate"))
    XCTAssertEqual(p.action, .push, "retries the action that failed")
  }

  /// An in-flight action outranks a stale failure — otherwise clicking Retry would keep showing the old
  /// error while the retry ran.
  func testInFlightOutranksAFailure() {
    let p = VCSSyncPresenter.make(
      state: state(), hasTarget: true, activity: .running(.push), failure: .locked,
      lastAction: .push, now: now)
    XCTAssertEqual(p.tone, .normal)
    XCTAssertEqual(p.title, "Pushing…")
  }

  /// A parked rebase must offer ABORT, never a retry — a retry fails identically until it's cleared.
  func testRebaseInProgressOffersAbortNotRetry() {
    let p = VCSSyncPresenter.make(
      state: state(), hasTarget: true, failure: .rebaseInProgress, lastAction: .pull, now: now)
    XCTAssertEqual(p.action, .abortRebase)
    XCTAssertTrue(p.isEnabled)
    XCTAssertTrue(p.subtitle.contains("Abort"))
  }

  /// The fix for a rejection is to pull, never to force — the engine has no force-push.
  func testRejectionOffersPull() {
    let p = VCSSyncPresenter.make(
      state: state(ahead: 2), hasTarget: true, failure: .rejected("! [rejected]"), lastAction: .push,
      now: now)
    XCTAssertEqual(p.action, .pull)
  }

  /// Nothing a click can do about a missing binary.
  func testToolMissingOffersNoAction() {
    let p = VCSSyncPresenter.make(
      state: state(), hasTarget: true, failure: .toolMissing("git"), lastAction: .fetch, now: now)
    XCTAssertNil(p.action)
    XCTAssertFalse(p.isEnabled)
  }

  func testAuthFailureCopyIsWrittenNotRawStderr() {
    let raw = "fatal: could not read Username for 'https://github.com': terminal prompts disabled"
    let message = VCSSyncPresenter.describe(.authRequired(raw))
    XCTAssertFalse(message.contains("terminal prompts disabled"), "raw stderr is baffling here")
    XCTAssertTrue(message.contains("ssh-agent") || message.contains("credential helper"))
  }

  func testHostKeyCopyIsDistinctFromAuthCopy() {
    let host = VCSSyncPresenter.describe(.hostKeyUnverified("Host key verification failed."))
    let auth = VCSSyncPresenter.describe(.authRequired("Permission denied (publickey)."))
    XCTAssertNotEqual(host, auth, "telling them to fix credentials would be wrong advice")
    XCTAssertTrue(host.contains("key isn’t known"))
  }

  func testOtherFailureShowsOnlyTheFirstLine() {
    let message = VCSSyncPresenter.describe(.other("first line\nsecond line\nthird"))
    XCTAssertEqual(message, "first line")
  }

  // MARK: Copy invariants

  /// `remote.pushDefault` can make the push remote something other than `origin`, so no string may
  /// hardcode it.
  func testRemoteNameIsInterpolatedNotHardcoded() {
    let s = state(remotes: ["upstream"])
    for p in [
      VCSSyncPresenter.make(state: s, hasTarget: true, now: now),
      VCSSyncPresenter.make(
        state: state(ahead: 1, remotes: ["upstream"]), hasTarget: true, now: now),
      VCSSyncPresenter.make(
        state: state(behind: 1, remotes: ["upstream"]), hasTarget: true, now: now),
      VCSSyncPresenter.make(
        state: state(ahead: 1, behind: 1, remotes: ["upstream"]), hasTarget: true, now: now),
      VCSSyncPresenter.make(
        state: state(gone: true, remotes: ["upstream"]), hasTarget: true, now: now),
    ] {
      let text = ((p.title ?? "") + p.subtitle + p.help + p.accessibility)
      XCTAssertFalse(text.contains("origin"), "hardcoded origin in: \(text)")
    }
  }

  /// The `ViewThatFits` ladder tries variants in order, so the longest MUST be first. Inverting this
  /// silently defeats the whole ladder — the first variant always fits.
  func testTitleVariantsAreOrderedLongestFirst() {
    for p in [
      VCSSyncPresenter.make(state: state(ahead: 1), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(behind: 1), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(gone: true), hasTarget: true, now: now),
    ] {
      let lengths = p.titleVariants.map(\.count)
      XCTAssertEqual(
        lengths, lengths.sorted(by: >), "longest first, got \(p.titleVariants)")
      XCTAssertFalse(p.titleVariants.isEmpty)
    }
  }

  func testEveryEnabledStateHasAnAction() {
    for p in [
      VCSSyncPresenter.make(state: state(ahead: 1), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(behind: 1), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(ahead: 1, behind: 1), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(gone: true), hasTarget: true, now: now),
      VCSSyncPresenter.make(state: state(), hasTarget: true, now: now),
    ] {
      XCTAssertTrue(p.isEnabled)
      XCTAssertNotNil(p.action, "an enabled segment must do something when clicked")
      XCTAssertFalse(p.help.isEmpty)
      XCTAssertFalse(p.accessibility.isEmpty)
    }
  }

  // MARK: fetchedAgo

  func testSubMinuteReadsJustNow() {
    XCTAssertEqual(
      VCSSyncPresenter.fetchedAgo(.at(now), now: now), "Last fetched just now",
      "RelativeDateTimeFormatter would say 'in 0 seconds' here")
    XCTAssertEqual(
      VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-59)), now: now),
      "Last fetched just now")
  }

  func testMinutesHoursAndDays() {
    XCTAssertEqual(
      VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-540)), now: now),
      "Last fetched 9 minutes ago", "the string from the reference screenshot")
    XCTAssertTrue(
      VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-5400)), now: now).contains("hour"))
    XCTAssertTrue(
      VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-259_200)), now: now).contains("day"))
  }

  func testShortFormIsShorter() {
    let full = VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-540)), now: now)
    let short = VCSSyncPresenter.fetchedAgo(.at(now.addingTimeInterval(-540)), now: now, short: true)
    XCTAssertLessThan(short.count, full.count)
    XCTAssertTrue(short.hasPrefix("Fetched"))
  }

  func testNeverAndUnknownAreDifferentFacts() {
    XCTAssertEqual(VCSSyncPresenter.fetchedAgo(.never, now: now), "Never fetched")
    XCTAssertEqual(
      VCSSyncPresenter.fetchedAgo(.unknown, now: now), "",
      "unknown means we couldn't tell — rendering 'never' would be a claim we can't make")
  }
}

